def _check_stubs_siwen(cfg: dict) -> list[str]:
    """斯文版 check_stubs：不以 CJK slug 為 garbage，短文限放至 30 字。"""
    import frontmatter as _fm
    issues = []
    concepts_dir = _Path(cfg["paths"]["concepts"])
    for md_file in concepts_dir.glob("*.md"):
        post = _fm.load(str(md_file))
        title = post.metadata.get("title", "")
        summary = post.metadata.get("summary", "")
        content = post.content.strip()
        slug = md_file.stem
        if "English Title / 中文标题" in title:
            issues.append(f"未填之模：{slug}")
        elif "One-line summary in English" in summary:
            issues.append(f"未填之模：{slug}")
        elif title.replace(".", "").replace("/", "").replace(" ", "") == "":
            issues.append(f"空題：{slug}")
        elif "has not been fully written" in content or "has not been written yet" in content:
            issues.append(f"佔位之殘：{slug}")
        elif "尚未完成撰写" in content:
            issues.append(f"佔位之殘：{slug}")
        elif any(leak in summary.lower() for leak in [
            "the user says", "the user wants", "the user asks", "the user is",
        ]):
            issues.append(f"LLM 漏辭：{slug}")
        # 不以 CJK slug 為 garbage——斯文之 slug 恰為 CJK
        elif len(content) < 30 and not post.metadata.get("stub"):
            issues.append(f"近空之條：{slug}（{len(content)} 字）")
    return issues
